#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Fixture for tests/frames_erfa_vector_oracle.rs.

Step 1 (--epochs-only) writes epochs.csv from the fixed rules of the pre-registration.
Step 2 runs the oracle, pyerfa (ERFA, the BSD-licensed release of the SOFA routines), and
writes erfa.csv: per epoch, the 9 elements (row-major) of
  P   = erfa.pmat06(tt1, tt2)                                  (IAU 2006 bias-precession)
  T   = P^T . N^T . Rz(-EE), the TEME->GCRS matrix, with
        N  = erfa.numat(erfa.obl06, dpsi, deps), (dpsi, deps) = erfa.nut00b(tt1, tt2)
        EE = dpsi cos(obl06) + erfa.eect00(tt1, tt2)
  C   = erfa.c2ixys(X + dX, Y + dY, s), (X, Y, s) = erfa.xys06a(tt1, tt2)
Run from the repository root (pyerfa 2.0.1.5, numpy):
    python -I tests/fixtures/frames_erfa_vector_oracle/generate_frames_erfa_vector_oracle.py [--epochs-only]
"""
import csv
import random
import sys
from pathlib import Path

DIR = Path(__file__).resolve().parent
MAS = 1e-3 / 3600.0 * 3.141592653589793 / 180.0


def epochs():
    rows = [
        (2451545.0, 0.0, 0.0),            # J2000.0
        (2444239.5, 0.0, 0.0),            # 1980-01-01
        (2459000.5, 0.15, -0.25),         # 2020-05-31
        (2469807.5, -0.3, 0.3),           # 2050-01-01
    ]
    rng = random.Random(20261013)
    lo, hi = 2433282.5, 2488069.5         # 1950-01-01 .. 2100-01-01
    for _ in range(36):
        day = float(rng.randint(int(lo), int(hi))) + 0.5
        frac = round(rng.random(), 9)
        dx = round(rng.uniform(-0.5, 0.5), 4)
        dy = round(rng.uniform(-0.5, 0.5), 4)
        rows.append((day + frac, dx, dy))
    return rows


def main():
    step = 1 if len(sys.argv) > 1 and sys.argv[1] == "--epochs-only" else 2
    rows = epochs()
    with open(DIR / "epochs.csv", "w", newline="") as f:
        f.write("# jd_tt,dx_mas,dy_mas (generated by generate_frames_erfa_vector_oracle.py)\n")
        w = csv.writer(f, lineterminator="\n")
        for (jd, dx, dy) in rows:
            w.writerow([repr(jd), repr(dx), repr(dy)])
    if step == 1:
        return
    import erfa
    import numpy as np
    with open(DIR / "erfa.csv", "w", newline="") as f:
        f.write(f"# pyerfa {erfa.__version__} (liberfa {erfa.version.erfa_version}): "
                "P[9], T[9], C[9] row-major, see the generator docstring\n")
        w = csv.writer(f, lineterminator="\n")
        for (jd, dx, dy) in rows:
            tt1, tt2 = jd, 0.0
            p = erfa.pmat06(tt1, tt2)
            dpsi, deps = erfa.nut00b(tt1, tt2)
            epsa = erfa.obl06(tt1, tt2)
            n = erfa.numat(epsa, dpsi, deps)
            ee = dpsi * np.cos(epsa) + erfa.eect00(tt1, tt2)
            t = p.T @ n.T @ erfa.rz(-ee, np.eye(3))
            x, y, s = erfa.xys06a(tt1, tt2)
            c = erfa.c2ixys(x + dx * MAS, y + dy * MAS, s)
            w.writerow([repr(float(v)) for m in (p, t, c) for v in np.asarray(m).ravel()])


if __name__ == "__main__":
    main()
